import { PdfStudioEngine } from '../assets/pdf-studio-engine.js';

const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
const frame=()=>new Promise(r=>requestAnimationFrame(r));
const S={engine:null,init:null,name:'Untitled.pdf',page:0,mode:'edit',tool:'select',selected:null,objects:[],annotations:[],history:[],redo:[],dirty:false,zoom:'fit',width:612,height:792,busy:false,drag:null,pending:null,image:null,signature:null,ocr:null,thumbToken:0};
let toastTimer;
function toast(message,error=false){$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,error?8500:5000);}
function fail(error){console.error('PDF Studio:',error?.message||error);toast(error?.message||'That action could not be completed.',true);}
async function busy(label,fn){if(S.busy)return;S.busy=true;$('busy-text').textContent=label;$('busy-detail').textContent='Working on your device.';$('busy').hidden=false;await frame();try{return await fn();}catch(e){fail(e);return null;}finally{$('busy').hidden=true;S.busy=false;}}
async function getEngine(){if(S.engine)return S.engine;if(!S.init)S.init=(async()=>{const response=await fetch('/assets/pdfium.wasm',{credentials:'same-origin'});if(!response.ok||!response.headers.get('content-type')?.includes('wasm'))throw new Error('The PDF engine could not load. Check your connection and site access, then try again.');const binary=await response.arrayBuffer();return PdfStudioEngine.create(binary);})();try{S.engine=await S.init;return S.engine;}catch(e){S.init=null;throw e;}}
function dialog(title,content,actions=[['cancel','Cancel',''],['ok','Continue','primary']]){const d=$('app-dialog');$('dialog-title').textContent=title;$('dialog-content').innerHTML=content;$('dialog-actions').innerHTML=actions.map(([value,label,cls])=>`<button value="${esc(value)}" class="btn ${cls}" ${value==='cancel'?'formnovalidate':''}>${esc(label)}</button>`).join('');d.returnValue='cancel';return new Promise(resolve=>{d.onclose=()=>{d.onclose=null;resolve(d.returnValue);};d.showModal();});}
async function confirm(title,message,label='Continue'){return(await dialog(title,`<p>${message}</p>`,[['cancel','Cancel',''],['ok',label,'primary']]))==='ok';}
async function promptValue(title,label,type='text',value='',note=''){const result=await dialog(title,`<label class="field"><span>${esc(label)}</span><input id="prompt-value" type="${type}" value="${esc(value)}" autocomplete="off" required></label>${note?`<p class="small-note">${esc(note)}</p>`:''}`);return result==='ok'?$('prompt-value').value:null;}
async function allowReplace(){return!S.dirty||await confirm('Open another document?','Download your current PDF first if you want to keep these edits. Opening another document clears this workspace.','Open document');}
function controls(){const loaded=!!S.engine?.doc;if(!loaded)return;const info=S.engine.info();$('doc-name').textContent=S.name;$('doc-state').textContent=(S.dirty?'Unsaved changes':'Ready')+' · '+info.count+' page'+(info.count===1?'':'s');$('undo-btn').disabled=!S.history.length;$('redo-btn').disabled=!S.redo.length;$('page-total').textContent=info.count;$('page-of').textContent='/ '+info.count;$('page-input').value=S.page+1;$('page-input').max=info.count;$('prev-btn').disabled=S.page===0;$('next-btn').disabled=S.page===info.count-1;
  const notes=[];if(!info.editable)notes.push('Content editing is restricted. Use the owner password from Export & protect. Form filling may still be permitted.');if(info.signatures)notes.push('This document has a certificate signature. Editing changes its signed content. PDF Studio adds visible signatures; it does not certify documents.');if(info.encrypted)notes.push('Password-protected PDF. Downloads retain protection unless you remove it.');$('document-notice').hidden=!notes.length;$('document-notice').textContent=notes.join(' ');
}
function reset(){S.page=0;S.mode='edit';S.tool='select';S.selected=null;S.pending=null;S.history=[];S.redo=[];S.dirty=false;S.ocr=null;S.zoom='fit';$('zoom-select').value='fit';$('welcome').hidden=true;$('workspace').hidden=false;tabs();toolbar();}
async function opened(){reset();await render(true);controls();}
async function openFile(file){if(!file)return;if(file.size>50*1024*1024){toast('Choose a PDF smaller than 50 MB.',true);return;}if(!await allowReplace())return;
  await busy('Opening your PDF…',async()=>{const data=await file.arrayBuffer();if(!new TextDecoder().decode(new Uint8Array(data).slice(0,1024)).includes('%PDF-'))throw new Error('Choose a valid PDF file.');const engine=await getEngine();let password='';try{engine.load(data);}catch(e){if(e.code!==4)throw e;password=await promptValue('Password required','PDF password','password');if(password===null)return;engine.load(data,password);}S.name=file.name;await opened();});
}
async function newDoc(){if(!await allowReplace())return;await busy('Creating a document…',async()=>{const e=await getEngine();e.create();S.name='Untitled.pdf';await opened();toast('A blank page is ready. Use Add text or Insert image to start.');});}
async function demo(){if(!await allowReplace())return;await busy('Preparing a sample document…',async()=>{const e=await getEngine();e.create();e.addText(0,'A little clarity goes a long way.',54,714,{size:25,color:'#152d49'});e.addText(0,'Leadership is a practice.',54,658,{size:15,color:'#235d97'});e.addText(0,'Select this sentence and change its words.\nThen move the text, add a note, or try a signature.',54,619,{size:12,color:'#526881'});e.addShape(0,'rect',[54,400,558,526],{color:'#edf4fd',fill:true,width:0});e.addText(0,'MAKE IT YOURS',74,495,{size:11,color:'#235d97'});e.addText(0,'A useful question for your next team meeting:\nWhat would make our work easier to understand?',74,466,{size:14,color:'#152d49'});e.addShape(0,'line',[54,362,558,362],{color:'#d9a54e',width:2});e.addText(0,'A fillable field to try:',54,326,{size:11,color:'#526881'});e.createField(0,[54,267,360,305],'YourName');e.createField(0,[54,213,74,233],'Ready',2);e.addText(0,'Ready to make a change',84,217,{size:11,color:'#152d49'});e.addText(0,'MAYNE LEADERSHIP  /  PDF STUDIO',54,54,{size:9,color:'#60738a'});e.addPage();e.addText(1,'Bring the pages together.',54,714,{size:25,color:'#152d49'});e.addText(1,'Try rotating, moving, duplicating, or extracting this page.\nYou can also merge another PDF into this document.',54,665,{size:13,color:'#526881'});S.name='PDF-Studio-Sample.pdf';await opened();});}
function currentSnapshot(){return{bytes:S.engine.save(),password:S.engine.password};}
function record(snapshot){S.history.push(snapshot);S.redo=[];let total=S.history.reduce((n,item)=>n+item.bytes.length,0);while(S.history.length>30||total>64*1024*1024){total-=S.history.shift().bytes.length;}S.dirty=true;}
async function mutate(label,fn,{pageRefresh=false,keepSelected=false}={}){if(!S.engine?.doc)return;return busy(label,async()=>{const snapshot=currentSnapshot(),oldPage=S.page;try{const result=await fn();if(result?.noChange)return result;S.engine.save();record(snapshot);if(!keepSelected)S.selected=null;S.pending=null;S.page=clamp(S.page,0,S.engine.info().count-1);await render(pageRefresh);controls();return result;}catch(e){S.engine.load(snapshot.bytes,snapshot.password);S.page=oldPage;S.selected=null;await render(true);controls();throw e;}});}
async function undo(redo=false){const from=redo?S.redo:S.history,to=redo?S.history:S.redo;if(!from.length||S.busy)return;await busy(redo?'Redoing the change…':'Undoing the change…',async()=>{const current=currentSnapshot(),previous=from.at(-1);S.engine.load(previous.bytes,previous.password);from.pop();to.push(current);S.selected=null;S.pending=null;S.ocr=null;S.dirty=true;S.page=clamp(S.page,0,S.engine.info().count-1);await render(true);controls();});}
function putCanvas(canvas,r){canvas.width=r.width;canvas.height=r.height;canvas.getContext('2d').putImageData(new ImageData(r.rgba,r.width,r.height),0,0);}
async function render(thumbnails=false){if(!S.engine?.doc)return;const size=S.engine.size(S.page);let zoom=S.zoom==='fit'?Math.max(.2,Math.min(1.8,($('viewport').clientWidth-62)/size.width)):Number(S.zoom);zoom=clamp(zoom,.2,3);S.width=Math.round(size.width*zoom);S.height=Math.round(size.height*zoom);$('page-surface').style.width=S.width+'px';$('page-surface').style.height=S.height+'px';$('overlay').setAttribute('viewBox',`0 0 ${S.width} ${S.height}`);$('render-label').hidden=false;const result=S.engine.render(S.page,zoom*Math.min(2,window.devicePixelRatio||1));putCanvas($('pdf-canvas'),result);$('render-label').hidden=true;S.objects=S.engine.objects(S.page);S.annotations=S.engine.annotations(S.page);$('page-size').textContent=Math.round(size.width)+' × '+Math.round(size.height)+' pt';controls();drawOverlay();inspect();if(thumbnails)queueThumbnails();else{document.querySelectorAll('.thumb').forEach(b=>b.classList.toggle('active',Number(b.dataset.page)===S.page));updateThumbnail(S.page);}if(!S.objects.some(o=>o.type===1)&&S.mode==='edit')$('tool-hint').textContent='No selectable text on this page. Try Scan & OCR for a scanned page.';}
function updateThumbnail(index){const canvas=document.querySelector(`.thumb[data-page="${index}"] canvas`);if(!canvas)return;try{const size=S.engine.size(index);putCanvas(canvas,S.engine.render(index,89/Math.max(size.width,size.height*.7)));canvas.hidden=false;canvas.previousElementSibling?.remove();}catch{}}
async function queueThumbnails(){const token=++S.thumbToken,count=S.engine.info().count;$('thumbnails').innerHTML=Array.from({length:count},(_,i)=>`<button class="thumb ${i===S.page?'active':''}" data-page="${i}" title="Go to page ${i+1}" aria-label="Page ${i+1}"><div class="thumb-placeholder"></div><canvas hidden></canvas><span>${i+1}</span></button>`).join('');const indices=[S.page,...Array.from({length:count},(_,i)=>i).filter(i=>i!==S.page)];for(const i of indices){if(token!==S.thumbToken)return;updateThumbnail(i);await frame();if(i!==S.page&&S.engine.pages.has(i)){const page=S.engine.pages.get(i);if(S.engine.form)S.engine.p.FORM_OnBeforeClosePage(page,S.engine.form);S.engine.p.FPDF_ClosePage(page);S.engine.pages.delete(i);}}}
async function goto(index){if(S.busy||!S.engine?.doc)return;const next=clamp(Number(index),0,S.engine.info().count-1);if(!Number.isFinite(next))return;S.page=next;S.selected=null;S.pending=null;await render();$('viewport').scrollTop=0;}
const icons={select:'M5 3v16l4-5 4 7 3-2-4-6 6-1z',text:'M4 5h16M12 5v15M8 20h8',image:'M3 4h18v16H3zM3 16l6-6 5 5 3-3 4 4M17 8h.01',find:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',ink:'M4 20l4-1 12-12-4-4L4 15zM14 5l4 4',rect:'M3 4h18v16H3z',ellipse:'M21 12a9 8 0 1 1-18 0 9 8 0 0 1 18 0',line:'M4 20L20 4',highlight:'M3 21h18M5 16l10-12 5 4-10 12z',comment:'M3 4h18v12H9l-6 4zM7 8h10M7 12h7',sign:'M3 19c5-11 8-14 8-10s-7 9-5 6c2-2 4-2 6-1s4-2 8-1',redact:'M3 4h18v16H3zM7 8h10M7 12h10M7 16h10',rotate:'M3 10a9 9 0 1 1 2 9M3 4v6h6',merge:'M6 3v8h12V3M12 11v10M8 17l4 4 4-4',page:'M6 3h8l4 4v14H6zM14 3v5h5',crop:'M6 3v15h15M3 6h15v15',form:'M3 4h18v16H3zM7 8h10M7 13h4M7 16h7',check:'M3 4h18v16H3zM6 12l4 4 8-8',ocr:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M7 10h10M7 14h10',export:'M12 3v13M8 12l4 4 4-4M3 16v5h18v-5',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v11H4zM12 14v3',details:'M4 3h16v18H4zM8 7h8M8 11h8M8 15h5',delete:'M3 6h18M6 6v15h12V6M9 6V3h6v3M10 10v7M14 10v7',stamp:'M6 14h12l3 7H3zM8 14V8a4 4 0 0 1 8 0v6'};
const svg=key=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[key]||icons.page}"/></svg>`;
const tools={edit:[['select','Select & move','select'],['text','Add text','text'],['image','Insert image','image'],['find','Find text','find']],annotate:[['select','Select','select'],['highlight','Highlight','highlight'],['ink','Draw','ink'],['rect','Rectangle','rect'],['ellipse','Ellipse','ellipse'],['line','Line','line'],['comment','Comment','comment'],['signature','Signature','sign'],['stamp','Stamp','stamp'],['redact','Redact','redact']],pages:[['select','Select','select'],['rotate','Rotate','rotate'],['blank','Add page','page'],['duplicate','Duplicate','page'],['move','Move page','merge'],['merge','Merge PDFs','merge'],['extract','Extract / split','export'],['crop','Crop','crop'],['deletePage','Delete page','delete']],forms:[['fill','Fill existing','form'],['field','Add text field','text'],['checkbox','Add checkbox','check'],['flatten','Flatten page','page']],scan:[['ocr','Recognize text','ocr'],['scanImage','Image to PDF','image']],export:[['download','Download PDF','export'],['pageImage','Page as image','image'],['exportText','Extract text','text'],['print','Print','page'],['compress','Smaller PDF','page'],['password','Set password','lock'],['owner','Owner password','lock'],['removePassword','Remove password','lock'],['details','Document details','details']]};
function tabs(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mode===S.mode)));}
function toolbar(){$('tool-strip').innerHTML=tools[S.mode].map(([id,label,icon])=>`<button class="tool ${id==='redact'||id==='deletePage'?'danger':''}" data-tool="${id}" aria-pressed="${S.tool===id}">${svg(icon)}${esc(label)}</button>`).join('');$('interaction-layer').classList.toggle('crosshair',!['select','fill','find'].includes(S.tool));const hints={select:'Click existing text or an image to edit it. Drag a selection to move it.',text:'Click on the page, then enter your text in the properties panel.',image:'Drag a rectangle on the page to place your image.',ink:'Draw directly on the page. Each stroke becomes PDF content.',highlight:'Drag across the area you want to highlight.',rect:'Drag a rectangle on the page.',ellipse:'Drag to draw an ellipse.',line:'Drag to draw a line.',comment:'Click the page to add a comment.',signature:'Drag a rectangle to place your signature.',stamp:'Click the page to place your stamp.',redact:'Drag a rectangle, then apply redaction to remove the content inside.',crop:'Drag around the part of the page to keep.',field:'Drag a rectangle to create a fillable text field.',checkbox:'Click to add a fillable checkbox.',fill:'Click a blue form field to fill it.'};$('tool-hint').textContent=hints[S.tool]||'Choose a tool above.';}
async function changeMode(mode){if(S.busy)return;S.mode=mode;S.selected=null;S.pending=null;S.tool=mode==='forms'?'fill':'select';tabs();toolbar();drawOverlay();inspect();}
function field(id,label,value,type='text'){return `<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(value)}"></label>`;}
const fontOptions=`<option value="original">Original font</option><option value="Helvetica">Sans serif</option><option value="Helvetica-Bold">Sans serif bold</option><option value="Times-Roman">Serif</option><option value="Times-Bold">Serif bold</option><option value="Courier">Monospace</option>`;
function inspect(){const el=$('inspector');$('properties-title').textContent='Make an edit';$('property-badge').textContent='PDF CONTENT';if(!S.engine?.doc)return;
  if(S.pending?.kind==='text'){ $('properties-title').textContent='Add text';el.innerHTML=`<label class="field"><span>Your text</span><textarea id="text-value" placeholder="Type your text…" autofocus></textarea></label><div class="field-row">${field('text-size','Size (pt)',14,'number')}<label class="field"><span>Font</span><select id="text-font">${fontOptions.replace('<option value="original">Original font</option>','')}</select></label></div>${field('text-color','Text color','#152d49','color')}<button id="apply-text" class="btn primary full">Add to PDF</button><p class="small-note">Line breaks create separate editable lines.</p>`;return; }
  if(S.pending?.kind==='redact'){ $('properties-title').textContent='Apply redaction';$('property-badge').textContent='REMOVE PAGE CONTENT';el.innerHTML=`<div class="help-box gold">Redaction removes the text and image content inside your selected rectangle. Inspect the exported PDF before sharing. Metadata, comments, and attachments elsewhere are not sanitized.</div><button id="apply-redaction" class="btn danger full">Apply redaction</button><button id="cancel-pending" class="btn full">Cancel selection</button>`;return;}
  if(S.pending?.kind==='crop'){ $('properties-title').textContent='Crop page';el.innerHTML=`<p>Keep the area inside your selection.</p><div class="help-box gold">Cropping changes the visible page area. Content outside the crop remains in the file. Use Redact to remove content.</div><button id="apply-crop" class="btn primary full">Crop to selection</button><button id="cancel-pending" class="btn full">Cancel</button>`;return; }
  const item=S.selected;
  if(item?.annotIndex!==undefined){$('properties-title').textContent=item.type===20?'Form field':'Comment';$('property-badge').textContent=item.type===20?'FILLABLE PDF':'ANNOTATION';
    if(item.type===20){const type=item.fieldType;el.innerHTML=`<p><strong>${esc(item.name||'Unnamed field')}</strong></p>${type===2||type===3?`<label class="checkbox-field"><input id="field-value" type="checkbox" ${item.checked?'checked':''}>Checked</label>`:type===4||type===5?`<label class="field"><span>Value</span><select id="field-value">${item.options.map(x=>`<option ${x===item.value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`:type===6?`<label class="field"><span>Value</span><textarea id="field-value">${esc(item.value)}</textarea></label>`:`<p>This field type is not supported for editing. Certificate signatures and XFA forms require a dedicated application.</p>`}${[2,3,4,5,6].includes(type)?`<button id="apply-field" class="btn primary full" ${item.flags&1?'disabled':''}>Save field value</button>`:''}${item.flags&1?'<p class="small-note">This field is read-only.</p>':''}<button id="remove-selected" class="btn danger full">Delete field</button>`;}
    else el.innerHTML=`<p>${esc(item.label||'PDF annotation')}</p><button id="remove-selected" class="btn danger full">Delete annotation</button>`;
    return;
  }
  if(item){$('properties-title').textContent=item.type===1?'Edit existing text':item.type===3?'Edit image':item.label;$('property-badge').textContent='EXISTING PDF OBJECT';
    const r=item.rect;const hex=item.color?'#'+item.color.slice(0,3).map(v=>v.toString(16).padStart(2,'0')).join(''):'#152d49';
    el.innerHTML=(item.type===1?`<label class="field"><span>Text</span><textarea id="text-value">${esc(item.text)}</textarea></label><div class="field-row">${field('text-size','Size (pt)',Math.round(item.size*100)/100,'number')}<label class="field"><span>Font</span><select id="text-font">${fontOptions}</select></label></div>${field('text-color','Text color',hex,'color')}<label class="checkbox-field"><input id="text-fit" type="checkbox">Fit to original width</label><button id="apply-text" class="btn primary full">Apply text edit</button><p class="small-note">${esc(item.font||'Embedded font')}. A font substitution may be needed for letters absent from a subset font. PDF edits do not reflow other paragraphs.</p>`:item.type===3?`<p>Drag the image to move it, change its size, or select a replacement.</p><button id="replace-image" class="btn primary full">Replace image</button>`:item.type===5?'<div class="help-box gold">This is a grouped object. You can move, resize, or remove the group. Text inside a complex group is not directly editable in this version.</div>':'<p>Move, resize, recolor, or remove this graphic.</p>')+`<h3>Position &amp; size</h3><div class="field-row">${field('object-x','Left (pt)',Math.round(r[0]*10)/10,'number')}${field('object-y','Bottom (pt)',Math.round(r[1]*10)/10,'number')}</div><div class="field-row">${field('object-w','Width (pt)',Math.round((r[2]-r[0])*10)/10,'number')}${field('object-h','Height (pt)',Math.round((r[3]-r[1])*10)/10,'number')}</div><button id="apply-geometry" class="btn full">Apply position &amp; size</button>${item.type===2?field('shape-color','Color','#235d97','color')+'<button id="apply-shape-color" class="btn full">Apply color</button>':''}<button id="remove-selected" class="btn danger full">Delete selected object</button>`;
    return;
  }
  if(S.mode==='scan'){ $('properties-title').textContent='Scan & OCR';$('property-badge').textContent='ENGLISH TEXT RECOGNITION';el.innerHTML=S.ocr&&S.ocr.page===S.page?`<p>Recognized text from this page. Review it carefully before using it.</p><label class="field"><span>Recognized text</span><textarea id="ocr-text" style="min-height:210px">${esc(S.ocr.text)}</textarea></label><button id="copy-ocr" class="btn full">Copy recognized text</button><button id="download-ocr" class="btn full">Download text</button><button id="ocr-searchable" class="btn primary full">Add searchable text layer</button><button id="ocr-editable" class="btn full">Convert scan text to editable text</button><div class="help-box gold">OCR can make mistakes. Editable conversion replaces recognized lines with a standard font while retaining other image areas. Exact scan formatting is not preserved.</div>`:`<div class="empty-icon">⌕</div><p>Recognize English text in an image or scanned PDF. Work on one page at a time.</p><button id="start-ocr" class="btn primary full">Recognize this page</button><div class="help-box">The recognition engine runs on your device. An English language pack downloads the first time. The document is not uploaded.</div>`;return;}
  if(S.mode==='export'){ $('properties-title').textContent='Ready to share';$('property-badge').textContent='EXPORT OPTIONS';el.innerHTML=`<p>Download a new PDF with your edits. Your original file on your device is never overwritten.</p><div class="export-options"><button id="export-pdf" class="btn primary">Download edited PDF ↓</button><button id="export-image" class="btn">Export this page as PNG</button><button id="export-text" class="btn">Download document text</button><button id="export-print" class="btn">Print current PDF</button></div><h3>Password protection</h3><p class="small-note">You can add or remove a document password. A forgotten password cannot be recovered by this editor.</p><button id="export-password" class="btn full">Set password</button><div class="help-box">Visible signatures are supported. Digital certificate signing, PDF to Word conversion, and advanced accessibility remediation are not available.</div>`;return;}
  if(S.mode==='pages'){ $('properties-title').textContent='Organize your pages';$('property-badge').textContent='DOCUMENT STRUCTURE';el.innerHTML=`<p>Use the thumbnails to navigate. The toolbar lets you rotate, duplicate, move, crop, merge, or extract pages.</p>${field('move-target','Move current page to position',S.page+1,'number')}<button id="move-page-apply" class="btn full">Move page</button><button id="merge-pdfs" class="btn primary full">Merge PDFs</button><button id="extract-pages" class="btn full">Extract selected pages</button><div class="help-box">Page extraction creates a separate file. Original bookmarks and advanced form relationships may not carry into merged or extracted files.</div>`;return;}
  if(S.mode==='forms'){ $('properties-title').textContent='Fill & build forms';$('property-badge').textContent='INTERACTIVE PDF FIELDS';const fields=S.annotations.filter(a=>a.type===20);el.innerHTML=`<p>Click a highlighted form field on the page, or choose one below. Draw new fields with the toolbar.</p>${fields.length?'<div class="field-list">'+fields.map(a=>`<button class="object-item" data-annotation="${a.annotIndex}"><span>▤</span><span>${esc(a.name||'Field')}</span></button>`).join('')+'</div>':'<div class="help-box">No standard form fields found on this page. Add a text field or checkbox to make it fillable.</div>'}<h3>Flatten this page</h3><p class="small-note">Flattening turns fields and annotations into fixed page content.</p><button id="flatten-page" class="btn full">Flatten current page</button>`;return;}
  if(S.mode==='annotate'&&S.tool!=='select'){ $('properties-title').textContent=S.tool==='signature'?'Place a signature':S.tool==='stamp'?'Place a stamp':'Style your markup';$('property-badge').textContent='ANNOTATE & SIGN';el.innerHTML=`<p>${esc($('tool-hint').textContent)}</p>${field('tool-color','Color',S.tool==='highlight'?'#ffd34f':'#235d97','color')}${field('tool-width','Line width (pt)',S.tool==='highlight'?1:2,'number')}<label class="checkbox-field"><input id="tool-fill" type="checkbox" ${S.tool==='highlight'?'checked':''}>Fill shape</label>${S.tool==='redact'?'<div class="help-box gold">A black rectangle is not sufficient for redaction. Use the Redact tool and apply the selection to remove the underlying page content.</div>':''}`;return;}
  $('properties-title').textContent='Select something to edit';el.innerHTML=`<div class="empty-icon">↖</div><p>Click text, an image, or a graphic on the page. You can also select an object below.</p><div class="help-box">Drag a selected object to move it. Use the properties panel to change text, appearance, position, and size.</div><h3>Objects on this page <span style="color:#8c9aaa">${S.objects.length}</span></h3><div class="object-list">${S.objects.slice(0,250).map(o=>`<button class="object-item" data-object="${o.index}" title="${esc(o.label)}"><span>${o.type===1?'T':o.type===3?'▧':o.type===5?'▦':'◇'}</span><span>${esc(o.label)}</span></button>`).join('')}</div>`;
}
function drawOverlay(hover=null){const parts=[];if(S.mode==='forms')for(const a of S.annotations.filter(x=>x.type===20)){const r=S.engine.screenRect(S.page,a.rect,S.width,S.height);parts.push(`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="#235d9720" stroke="#235d9770" stroke-dasharray="3 2" stroke-width="1"/>`);}for(const [item,color]of [[hover,'#235d9755'],[S.selected,'#235d97']])if(item){const r=S.engine.screenRect(S.page,item.rect,S.width,S.height);parts.push(`<rect x="${r.x-3}" y="${r.y-3}" width="${r.w+6}" height="${r.h+6}" fill="none" stroke="${color}" stroke-width="1.3"/>`);if(item===S.selected)for(const[x,y]of[[r.x-3,r.y-3],[r.x+r.w+3,r.y-3],[r.x-3,r.y+r.h+3],[r.x+r.w+3,r.y+r.h+3]])parts.push(`<rect x="${x-3}" y="${y-3}" width="6" height="6" fill="white" stroke="${color}"/>`);}if(S.pending?.rect){const r=S.pending.rect;parts.push(`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="${S.pending.kind==='redact'?'#11111160':'#235d971a'}" stroke="${S.pending.kind==='redact'?'#a13535':'#235d97'}" stroke-width="1.5" stroke-dasharray="5 3"/>`);}$('overlay').innerHTML=parts.join('');}
function pageXY(event){const r=$('interaction-layer').getBoundingClientRect();return{x:(event.clientX-r.left)*S.width/r.width,y:(event.clientY-r.top)*S.height/r.height};}
function hit(x,y,fields=false){if(fields)return [...S.annotations].reverse().find(a=>{const r=S.engine.screenRect(S.page,a.rect,S.width,S.height);return x>=r.x-4&&x<=r.x+r.w+4&&y>=r.y-4&&y<=r.y+r.h+4;});const hits=S.objects.filter(o=>{const r=S.engine.screenRect(S.page,o.rect,S.width,S.height);return x>=r.x-3&&x<=r.x+r.w+3&&y>=r.y-3&&y<=r.y+r.h+3;});return hits.reverse().sort((a,b)=>(a.type===1?-1:b.type===1?1:0))[0]||null;}
function select(item){S.selected=item;S.pending=null;drawOverlay();inspect();}
function rectFrom(a,b){return{x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(b.x-a.x),h:Math.abs(b.y-a.y)};}
function pointerDown(event){if(S.busy||!S.engine?.doc||event.button!==0)return;const point=pageXY(event);if(S.tool==='select'||S.tool==='fill'){const a=hit(point.x,point.y,S.tool==='fill');select(a);if(a?.ptr){S.drag={kind:'move',start:point,last:point,item:a};$('interaction-layer').setPointerCapture(event.pointerId);}return;}if(S.tool==='text'){const [x,y]=S.engine.devicePoint(S.page,point.x,point.y,S.width,S.height);S.pending={kind:'text',point:[x,y]};inspect();setTimeout(()=>$('text-value')?.focus(),0);return;}S.drag={kind:S.tool,start:point,last:point,points:[point],style:{color:$('tool-color')?.value||(S.tool==='highlight'?'#ffd34f':'#235d97'),width:clamp(Number($('tool-width')?.value)||2,.1,30),fill:!!$('tool-fill')?.checked}};$('interaction-layer').setPointerCapture(event.pointerId);}
function pointerMove(event){if(S.busy||!S.engine?.doc)return;const point=pageXY(event);if(!S.drag){if(S.tool==='select')drawOverlay(hit(point.x,point.y));return;}S.drag.last=point;if(S.drag.kind==='ink'){S.drag.points.push(point);$('overlay').innerHTML=`<polyline points="${S.drag.points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${S.drag.style.color}" stroke-width="${S.drag.style.width*S.width/S.engine.size(S.page).width}" stroke-linecap="round" stroke-linejoin="round"/>`;}else if(S.drag.kind==='move'){const r=S.engine.screenRect(S.page,S.drag.item.rect,S.width,S.height),dx=point.x-S.drag.start.x,dy=point.y-S.drag.start.y;$('overlay').innerHTML=`<rect x="${r.x+dx-3}" y="${r.y+dy-3}" width="${r.w+6}" height="${r.h+6}" fill="#235d9714" stroke="#235d97" stroke-width="1.5"/>`;}else{S.pending={kind:S.drag.kind,rect:rectFrom(S.drag.start,point)};drawOverlay();}}
async function pointerUp(event){if(!S.drag)return;const drag=S.drag;S.drag=null;const end=pageXY(event);if($('interaction-layer').hasPointerCapture(event.pointerId))$('interaction-layer').releasePointerCapture(event.pointerId);if(drag.kind==='move'){if(Math.hypot(end.x-drag.start.x,end.y-drag.start.y)<3){drawOverlay();return;}const a=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height),b=S.engine.devicePoint(S.page,end.x,end.y,S.width,S.height);await mutate('Moving the object…',()=>S.engine.moveObject(S.page,drag.item,b[0]-a[0],b[1]-a[1]));return;}const screenRect=rectFrom(drag.start,end);let rect=S.engine.pageRect(S.page,screenRect,S.width,S.height);
  if(drag.kind==='ink'){const points=drag.points.map(p=>S.engine.devicePoint(S.page,p.x,p.y,S.width,S.height));await mutate('Adding your drawing…',()=>S.engine.addInk(S.page,points,drag.style));return;}
  if(drag.kind==='comment'){const text=await promptValue('Add a comment','Comment');if(text){const p=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height);await mutate('Adding comment…',()=>S.engine.comment(S.page,[p[0],p[1]-18,p[0]+18,p[1]],text));}return;}
  if(drag.kind==='checkbox'){const p=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height);const name=await promptValue('Add a checkbox','Field name','text','Checkbox'+Date.now().toString().slice(-5));if(name)await mutate('Adding form field…',()=>S.engine.createField(S.page,[p[0],p[1]-16,p[0]+16,p[1]],name,2));return;}
  if(drag.kind==='stamp'){const p=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height);const text=S.stamp||'DRAFT';await mutate('Adding stamp…',()=>{S.engine.addShape(S.page,'rect',[p[0],p[1]-35,p[0]+Math.max(100,text.length*12),p[1]],{color:'#235d97',width:2});S.engine.addText(S.page,text,p[0]+10,p[1]-24,{size:17,font:'Helvetica-Bold',color:'#235d97'});});return;}
  if(screenRect.w<5||screenRect.h<5){if(drag.kind==='line'&&Math.hypot(end.x-drag.start.x,end.y-drag.start.y)>5){const a=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height),b=S.engine.devicePoint(S.page,end.x,end.y,S.width,S.height);await mutate('Adding line…',()=>S.engine.addShape(S.page,'line',[...a,...b],drag.style));}else{S.pending=null;drawOverlay();}return;}
  if(drag.kind==='redact'||drag.kind==='crop'){S.pending={kind:drag.kind,rect:screenRect,pageRect:rect};drawOverlay();inspect();return;}
  if(drag.kind==='field'){const name=await promptValue('Add a text field','Field name','text','TextField'+Date.now().toString().slice(-5));if(name)await mutate('Adding form field…',()=>S.engine.createField(S.page,rect,name));return;}
  if(drag.kind==='image'||drag.kind==='signature'){const data=drag.kind==='signature'?S.signature:S.image;if(!data){toast('Choose an image or create a signature first.',true);return;}await mutate(drag.kind==='signature'?'Adding signature…':'Inserting image…',()=>S.engine.addImage(S.page,data,rect));return;}
  if(['rect','ellipse','highlight','line'].includes(drag.kind)){if(drag.kind==='line'){const a=S.engine.devicePoint(S.page,drag.start.x,drag.start.y,S.width,S.height),b=S.engine.devicePoint(S.page,end.x,end.y,S.width,S.height);rect=[...a,...b];}await mutate('Adding markup…',()=>S.engine.addShape(S.page,drag.kind==='highlight'?'rect':drag.kind,rect,{...drag.style,fill:drag.kind==='highlight'||drag.style.fill,opacity:drag.kind==='highlight'?80:255}));}
}
async function imageBytes(file){if(file.size>20*1024*1024)throw new Error('Choose an image smaller than 20 MB.');const bitmap=await createImageBitmap(file);try{const max=5000,ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw new Error('Could not read this image.');return new Uint8Array(await blob.arrayBuffer());}finally{bitmap.close();}}
async function chooseImage(replace=false,asPage=false){S.replaceImage=replace;S.imageAsPage=asPage;$('image-input').value='';$('image-input').click();}
async function handleImage(file){if(!file)return;await busy('Preparing your image…',async()=>{const data=await imageBytes(file);if(S.replaceImage&&S.selected?.type===3){const snapshot=currentSnapshot();try{S.engine.replaceImage(S.page,S.selected,data);record(snapshot);S.selected=null;await render();}catch(e){S.engine.load(snapshot.bytes,snapshot.password);throw e;}}else if(S.imageAsPage){S.imageAsPage=false;const snapshot=currentSnapshot();try{const at=S.engine.info().count;S.engine.addPage();const size=S.engine.size(at);S.engine.addImage(at,data,[0,0,size.width,size.height]);record(snapshot);S.page=at;await render(true);}catch(e){S.engine.load(snapshot.bytes,snapshot.password);throw e;}}else{S.image=data;S.tool='image';toolbar();inspect();toast('Drag a rectangle on the page to place the image.');}controls();});}
function downloadBytes(data,name,type='application/pdf'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const stem=()=>S.name.replace(/\.pdf$/i,'');
async function downloadPDF(){if(!S.engine?.doc)return;await busy('Saving your PDF…',async()=>{const bytes=S.engine.save();downloadBytes(bytes,stem()+'-edited.pdf');S.dirty=false;controls();toast('Your edited PDF has been downloaded.');});}
async function mergePDFs(files){let merged=0;for(const file of files){if(file.size>50*1024*1024){toast(file.name+' is larger than 50 MB.',true);continue;}const data=await file.arrayBuffer();let password='';const result=await mutate('Merging '+file.name+'…',async()=>{try{await S.engine.merge(data,password);return true;}catch(e){if(e.code===4)return{needsPassword:true,noChange:true};throw e;}},{pageRefresh:true});if(result===true)merged++;if(result?.needsPassword){password=await promptValue('Merge a protected PDF','Password for '+file.name,'password');if(password!==null){const added=await mutate('Merging protected PDF…',async()=>{await S.engine.merge(data,password);return true;},{pageRefresh:true});if(added===true)merged++;}}}if(merged)toast(merged+' PDF'+(merged===1?' has':'s have')+' been merged into your document.');}
function parsePages(value,count){const indices=[];for(const part of value.split(',')){const token=part.trim();if(!/^\d+(?:\s*-\s*\d+)?$/.test(token))throw new Error('Use page numbers such as 1, 3-5.');const [from,to=from]=token.split('-').map(Number);if(from<1||to<from||to>count)throw new Error('A page number is outside this document.');for(let i=from;i<=to;i++)indices.push(i-1);}return[...new Set(indices)];}
async function extractPages(){const input=await promptValue('Extract pages','Pages to extract','text',String(S.page+1),'Example: 1, 3-5. Creates a separate PDF.');if(input===null)return;await busy('Extracting pages…',async()=>{const indices=parsePages(input,S.engine.info().count);const data=await S.engine.extract(indices);downloadBytes(data,stem()+'-pages.pdf');toast('The selected pages have been downloaded.');});}
async function exportText(){await busy('Extracting document text…',async()=>{let text='';for(let i=0;i<S.engine.info().count;i++){text+='--- Page '+(i+1)+' ---\n\n'+S.engine.pageText(i)+'\n\n';if(i%5===0)await frame();}downloadBytes(text,stem()+'.txt','text/plain;charset=utf-8');});}
async function pageImage(){await busy('Exporting page image…',async()=>{const canvas=document.createElement('canvas');putCanvas(canvas,S.engine.render(S.page,2));const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw new Error('Could not export this page.');downloadBytes(await blob.arrayBuffer(),stem()+'-page-'+(S.page+1)+'.png','image/png');});}
async function printPDF(){await busy('Preparing print view…',async()=>{const url=URL.createObjectURL(new Blob([S.engine.save()],{type:'application/pdf'}));const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove();toast('Use Print in the PDF tab that opens. If it is blocked, download the PDF and print it.');setTimeout(()=>URL.revokeObjectURL(url),300000);});}
async function movePage(){const target=Number($('move-target')?.value);if(!Number.isInteger(target)||target<1||target>S.engine.info().count){toast('Enter a page position within this document.',true);return;}await mutate('Moving page…',()=>{S.engine.movePage(S.page,target-1);S.page=target-1;},{pageRefresh:true});}
async function documentDetails(){const m=S.engine.metadata();const r=await dialog('Document details',Object.entries(m).map(([key,value])=>field('meta-'+key,key,value)).join(''),[['cancel','Cancel',''],['ok','Save details','primary']]);if(r==='ok')await mutate('Updating document details…',()=>S.engine.setMetadata(Object.fromEntries(Object.keys(m).map(key=>[key,$('meta-'+key).value]))));}
async function passwordTool(){const r=await dialog('Set a document password',`${field('new-password','Password','','password')}${field('confirm-password','Confirm password','','password')}<p class="small-note">This password will be required to open downloaded copies of this PDF. Keep a record; PDF Studio cannot recover it.</p>`,[['cancel','Cancel',''],['ok','Set password','primary']]);if(r!=='ok')return;const pass=$('new-password').value;if(pass!==$('confirm-password').value){toast('The passwords do not match.',true);return;}await mutate('Protecting your PDF…',()=>S.engine.setPassword(pass));}
async function ownerTool(){const pass=await promptValue('Owner password','PDF owner password','password','', 'Use the document owner password to enable restricted content editing.');if(pass===null)return;await busy('Checking owner password…',async()=>{S.engine.unlockOwner(pass);controls();toast('Owner permissions enabled.');});}
async function signatureTool(){const r=dialog('Create a visible signature',`<p>Add a drawn or typed signature. This is a visible mark, not a certificate-based digital signature.</p><div class="signature-tabs"><button type="button" class="btn small primary" id="signature-draw-tab">Draw</button><button type="button" class="btn small" id="signature-type-tab">Type</button></div><div id="signature-draw-area"><canvas id="signature-canvas" class="signature-canvas" width="960" height="360"></canvas><button type="button" id="signature-clear" class="text-button">Clear drawing</button></div><div id="signature-type-area" hidden>${field('signature-name','Your signature','')}<div id="signature-preview" class="signature-preview"></div></div>`,[['cancel','Cancel',''],['ok','Use signature','primary']]);let mode='draw',drawing=false,hasInk=false;const canvas=$('signature-canvas'),ctx=canvas.getContext('2d');ctx.strokeStyle='#152d49';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';const position=event=>{const b=canvas.getBoundingClientRect();return[(event.clientX-b.left)*canvas.width/b.width,(event.clientY-b.top)*canvas.height/b.height];};canvas.onpointerdown=event=>{drawing=true;canvas.setPointerCapture(event.pointerId);ctx.beginPath();ctx.moveTo(...position(event));};canvas.onpointermove=event=>{if(!drawing)return;ctx.lineTo(...position(event));ctx.stroke();hasInk=true;};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;$('signature-clear').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hasInk=false;};$('signature-draw-tab').onclick=()=>{mode='draw';$('signature-draw-area').hidden=false;$('signature-type-area').hidden=true;};$('signature-type-tab').onclick=()=>{mode='type';$('signature-draw-area').hidden=true;$('signature-type-area').hidden=false;$('signature-name').focus();};$('signature-name').oninput=()=>{$('signature-preview').textContent=$('signature-name').value;};if(await r!=='ok')return;if(mode==='type'){const name=$('signature-name').value.trim();if(!name){toast('Type a signature first.',true);return;}ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#152d49';ctx.font='80px cursive';let size=80;while(ctx.measureText(name).width>canvas.width-60&&size>15){ctx.font=(--size)+'px cursive';}ctx.fillText(name,30,canvas.height/2+25);hasInk=true;}if(!hasInk){toast('Draw a signature first.',true);return;}const blob=await new Promise(res=>canvas.toBlob(res,'image/png'));S.signature=new Uint8Array(await blob.arrayBuffer());S.tool='signature';toolbar();inspect();toast('Drag a rectangle on the page to place your signature.');}
async function recognizePage(){await busy('Recognizing this page…',async()=>{const {recognize}=await import('/assets/pdf-ocr.js');const canvas=document.createElement('canvas');const result=S.engine.render(S.page,2);putCanvas(canvas,result);const data=await recognize(canvas,m=>{$('busy-detail').textContent=(m.status||'Recognizing')+' '+Math.round((m.progress||0)*100)+'%';});const lines=[];for(const block of data.blocks||[])for(const para of block.paragraphs||[])for(const line of para.lines||[])lines.push({text:line.text.trim(),bbox:line.bbox,confidence:line.confidence});S.ocr={page:S.page,text:data.text,lines,width:result.width,height:result.height};inspect();toast(lines.length?'OCR finished. Review the recognized text before converting.':'Text was recognized, but position data is unavailable. You can copy or download the text.');});}
async function applyOCR(editable=false){const data=S.ocr;if(!data||data.page!==S.page||!data.lines.length){toast('Recognize this page first. Position data is needed to add text.',true);return;}if(S.objects.some(o=>o.type===1)){if(!await confirm('Add OCR to a page with text?','This page already has PDF text. Adding OCR may duplicate it.','Continue'))return;}if(editable&&!await confirm('Convert scanned text?','Recognized lines will be removed from the image and replaced with standard-font PDF text. OCR and formatting can be inaccurate. Review the result carefully.','Convert text'))return;
  await mutate(editable?'Converting recognized text…':'Adding searchable text…',()=>{const e=S.engine;const lines=data.lines.filter(line=>line.text&&line.bbox);if(editable)for(const line of lines){const b=line.bbox,rect=e.pageRect(S.page,{x:b.x0-1,y:b.y0-1,w:b.x1-b.x0+2,h:b.y1-b.y0+2},data.width,data.height);e.redact(S.page,rect);e.addShape(S.page,'rect',rect,{color:'#ffffff',fill:true,width:0});}for(const line of lines){const b=line.bbox,rect=e.pageRect(S.page,{x:b.x0,y:b.y0,w:b.x1-b.x0,h:b.y1-b.y0},data.width,data.height),height=rect[3]-rect[1],size=clamp(height*.9,5,72);const objs=e.addText(S.page,line.text,rect[0],rect[1]+height*.1,{size,color:'#152d49'});for(const ptr of objs){const bounds=e.bounds(ptr),width=bounds[2]-bounds[0],target=rect[2]-rect[0];if(width>0)e.p.FPDFPageObj_Transform(ptr,target/width,0,0,1,rect[0]*(1-target/width),0);if(!editable)e.p.FPDFTextObj_SetTextRenderMode(ptr,3);}e.generate(S.page);}S.ocr=null;});
}
async function compress(){const r=await dialog('Create a smaller PDF',`<p>Create a separate PDF with pages flattened to compressed images. Text selection, interactive forms, annotations, links, bookmarks, and certificate signatures will not carry into this copy.</p><label class="field"><span>Image resolution</span><select id="compress-resolution"><option value="1.5">108 dpi · smaller file</option><option value="2" selected>144 dpi · balanced</option><option value="3">216 dpi · sharper</option></select></label><label class="field"><span>JPEG quality</span><select id="compress-quality"><option value=".6">60% · smaller file</option><option value=".8" selected>80% · balanced</option><option value=".9">90% · higher quality</option></select></label>`,[['cancel','Cancel',''],['ok','Create image PDF','primary']]);if(r!=='ok')return;const scale=Number($('compress-resolution').value),quality=Number($('compress-quality').value);await busy('Creating a compressed copy…',async()=>{const p=S.engine.p,e=new PdfStudioEngine(p);try{e.create();for(let i=0;i<S.engine.info().count;i++){const size=S.engine.size(i),canvas=document.createElement('canvas');putCanvas(canvas,S.engine.render(i,scale));const blob=await new Promise(res=>canvas.toBlob(res,'image/jpeg',quality));const data=new Uint8Array(await blob.arrayBuffer());if(i===0){e.closePages();p.FPDFPage_Delete(e.doc,0);}e.addPage(size.width,size.height);const obj=p.FPDFPageObj_NewImageObj(e.doc);const ok=e.bytes(data,ptr=>p.EPDFImageObj_SetJpeg(e.page(i),0,obj,ptr,data.length));if(!ok)throw new Error('Could not compress page '+(i+1));e.setMatrix(obj,[size.width,0,0,size.height,0,0]);p.FPDFPage_InsertObject(e.page(i),obj);e.generate(i);$('busy-detail').textContent='Page '+(i+1)+' of '+S.engine.info().count;await frame();}if(S.engine.info().encrypted)e.setPassword(S.engine.password);const bytes=e.save(),original=S.engine.save();downloadBytes(bytes,stem()+'-image-copy.pdf');toast(bytes.length<original.length?'Compressed PDF downloaded.':'Image PDF downloaded. This document did not become smaller at the chosen settings.');}finally{e.close();}});}
async function findText(){const term=await promptValue('Find text in this PDF','Search for');if(!term)return;const hits=[];await busy('Searching your PDF…',async()=>{for(let i=0;i<S.engine.info().count;i++){const text=S.engine.pageText(i),where=text.toLowerCase().indexOf(term.toLowerCase());if(where>=0)hits.push({page:i,text:text.slice(Math.max(0,where-45),where+term.length+70)});if(i%10===0)await frame();}});const r=dialog('Search results',hits.length?`<p>${hits.length} page${hits.length===1?'':'s'} contain this text. Scans need a searchable OCR layer.</p><div class="search-results">${hits.map(h=>`<button type="button" class="search-hit" data-search-page="${h.page}"><strong>Page ${h.page+1}</strong><br>${esc(h.text)}</button>`).join('')}</div>`:'<p>No matching selectable text was found. If this is a scan, use Scan &amp; OCR first.</p>',[['cancel','Close','']]);$('dialog-content').querySelectorAll('[data-search-page]').forEach(b=>b.onclick=()=>{$('app-dialog').close('cancel');goto(Number(b.dataset.searchPage));});await r;}
async function toolAction(id){if(S.busy||!S.engine?.doc)return;if(id==='image'){await chooseImage();return;}if(id==='signature'){await signatureTool();return;}if(id==='stamp'){const text=await promptValue('Create a stamp','Stamp text','text','DRAFT');if(text){S.stamp=text;S.tool='stamp';toolbar();inspect();}return;}if(id==='find'){await findText();return;}if(id==='rotate'){await mutate('Rotating page…',()=>S.engine.rotate(S.page),{pageRefresh:true});return;}if(id==='blank'){await mutate('Adding a page…',()=>{const size=S.engine.size(S.page);S.engine.addPage(size.width,size.height,S.page+1);S.page++;},{pageRefresh:true});return;}if(id==='duplicate'){await mutate('Duplicating page…',async()=>{await S.engine.duplicatePage(S.page);S.page++;},{pageRefresh:true});return;}if(id==='deletePage'){if(await confirm('Delete this page?','Remove page '+(S.page+1)+' from this document?','Delete page'))await mutate('Deleting page…',()=>S.engine.deletePage(S.page),{pageRefresh:true});return;}if(id==='move'){inspect();$('move-target')?.focus();return;}if(id==='merge'){$('merge-input').value='';$('merge-input').click();return;}if(id==='extract'){await extractPages();return;}if(id==='flatten'){if(await confirm('Flatten this page?','Form fields and annotations on this page will become fixed page content.','Flatten page'))await mutate('Flattening page…',()=>S.engine.flatten(S.page));return;}if(id==='scanImage'){await chooseImage(false,true);return;}if(id==='ocr'){await recognizePage();return;}if(id==='download'){await downloadPDF();return;}if(id==='pageImage'){await pageImage();return;}if(id==='exportText'){await exportText();return;}if(id==='print'){await printPDF();return;}if(id==='compress'){await compress();return;}if(id==='password'){await passwordTool();return;}if(id==='owner'){await ownerTool();return;}if(id==='removePassword'){if(await confirm('Remove document password?','Downloaded copies will open without the current password.','Remove password'))await mutate('Removing password…',()=>S.engine.removePassword());return;}if(id==='details'){await documentDetails();return;}S.tool=id;S.selected=null;S.pending=null;toolbar();drawOverlay();inspect();}
async function inspectorAction(id){if(S.busy)return;const item=S.selected;if(id==='apply-text'){const text=$('text-value').value,size=Number($('text-size').value),font=$('text-font').value,color=$('text-color').value;if(size<1||size>250||!Number.isFinite(size)){toast('Enter a text size between 1 and 250 points.',true);return;}if(S.pending?.kind==='text'){const point=S.pending.point;if(!text.trim())return;await mutate('Adding text…',()=>S.engine.addText(S.page,text,...point,{size,font,color}));}else if(item?.type===1){const fit=!!$('text-fit')?.checked;const result=await mutate('Editing existing text…',()=>S.engine.replaceText(S.page,item,text,{size,font,color,fit}));if(result?.fallback)toast('Text updated. A standard font was used for letters missing from the original font.');}return;}
  if(id==='remove-selected'){if(!item)return;if(item.type===20&&!await confirm('Delete this form field?','Remove this interactive field and all of its appearances from this document?','Delete field'))return;await mutate('Removing selection…',()=>item.annotIndex!==undefined?S.engine.removeAnnotation(S.page,item):S.engine.removeObject(S.page,item));return;}
  if(id==='apply-geometry'&&item){const x=Number($('object-x').value),y=Number($('object-y').value),w=Number($('object-w').value),h=Number($('object-h').value);if(![x,y,w,h].every(Number.isFinite)||w<=0||h<=0){toast('Enter valid position and positive size values.',true);return;}await mutate('Updating object position…',()=>{S.engine.resizeObject(S.page,item,w,h);const r=S.engine.bounds(item.ptr);S.engine.moveObject(S.page,item,x-r[0],y-r[1]);});return;}
  if(id==='apply-shape-color'&&item){const color=$('shape-color').value;await mutate('Applying graphic color…',()=>{S.engine.color(item.ptr,color);S.engine.color(item.ptr,color,255,true);S.engine.generate(S.page);});return;}
  if(id==='replace-image'){await chooseImage(true);return;}if(id==='apply-field'&&item){const input=$('field-value'),value=input.type==='checkbox'?input.checked:input.value;await mutate('Filling PDF field…',()=>S.engine.fillField(S.page,item,value));return;}
  if(id==='cancel-pending'){S.pending=null;drawOverlay();inspect();return;}if(id==='apply-redaction'&&S.pending){const rect=S.pending.pageRect;if(await confirm('Apply redaction?','Page content inside this rectangle will be removed from the PDF. Check the downloaded copy before sharing. This does not remove metadata or content elsewhere.','Apply redaction'))await mutate('Removing redacted content…',()=>S.engine.redact(S.page,rect));return;}if(id==='apply-crop'&&S.pending){const rect=S.pending.pageRect;await mutate('Cropping the page…',()=>S.engine.crop(S.page,rect),{pageRefresh:true});return;}
  const map={'move-page-apply':movePage,'extract-pages':extractPages,'export-pdf':downloadPDF,'export-image':pageImage,'export-text':exportText,'export-print':printPDF,'export-password':passwordTool,'start-ocr':recognizePage};if(map[id]){await map[id]();return;}if(id==='merge-pdfs'){$('merge-input').value='';$('merge-input').click();return;}if(id==='flatten-page'){await toolAction('flatten');return;}if(id==='copy-ocr'){try{await navigator.clipboard.writeText($('ocr-text').value);toast('Recognized text copied.');}catch{toast('Select and copy the recognized text from the text box.',true);}return;}if(id==='download-ocr'){downloadBytes($('ocr-text').value,stem()+'-ocr-page-'+(S.page+1)+'.txt','text/plain;charset=utf-8');return;}if(id==='ocr-searchable'){await applyOCR();return;}if(id==='ocr-editable'){await applyOCR(true);return;}
}
async function help(){await dialog('What PDF Studio can do',`<h3>Edit &amp; prepare</h3><ul><li>Change existing selectable text, with original-font handling and a standard-font fallback.</li><li>Add text and images; move, resize, replace, or delete page objects.</li><li>Draw, highlight, add shapes and comments, and place typed or drawn visible signatures.</li><li>Rotate, duplicate, move, crop, merge, and extract PDF pages.</li><li>Fill standard PDF forms and create text fields and checkboxes.</li><li>Recognize English scan text; add a searchable layer or convert recognized lines to editable text.</li><li>Remove page content using redaction; export PDFs, text, and page images.</li><li>Add or remove document passwords, update metadata, and make a flattened image PDF.</li></ul><h3>Limits to know</h3><p>This is a browser PDF editor, not a complete equivalent of Acrobat Pro. Exact font matching is not guaranteed. PDF text is often divided into small objects; other paragraphs do not reflow automatically. Complex object groups, XFA forms, certificate signing, PDF to Word conversion, and accessibility remediation are not supported. OCR needs review.</p><p>Redaction removes selected page content, but does not sanitize metadata, attachments, comments, or sensitive content elsewhere. Cropping only hides content outside the visible page area.</p><h3>Your files</h3><p>PDF and image bytes stay on your device. Nothing uploads your documents or saves them to a server. Work is kept in memory while this tab is open. Download to keep your changes. OCR downloads an English language pack the first time.</p><h3>Shortcuts</h3><p>Ctrl/Cmd+S: download · Ctrl/Cmd+Z: undo · Ctrl/Cmd+Shift+Z: redo · Delete: remove selection · Escape: clear selection.</p>`,[['cancel','Got it','primary']]);}
const safe=fn=>(...args)=>{try{return Promise.resolve(fn(...args)).catch(fail);}catch(e){fail(e);return Promise.resolve();}};
$('open-btn').onclick=()=>{$('file-input').value='';$('file-input').click();};$('new-btn').onclick=safe(newDoc);$('demo-btn').onclick=safe(demo);$('help-btn').onclick=safe(help);$('scope-btn').onclick=safe(help);$('file-input').onchange=safe(e=>openFile(e.target.files[0]));$('merge-input').onchange=safe(e=>mergePDFs([...e.target.files]));$('image-input').onchange=safe(e=>handleImage(e.target.files[0]));
$('dropzone').onclick=()=>{$('file-input').value='';$('file-input').click();};$('dropzone').onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();$('dropzone').click();}};for(const name of ['dragover','dragenter'])$('dropzone').addEventListener(name,event=>{event.preventDefault();$('dropzone').classList.add('dragover');});$('dropzone').ondragleave=()=>$('dropzone').classList.remove('dragover');$('dropzone').ondrop=safe(event=>{event.preventDefault();$('dropzone').classList.remove('dragover');return openFile(event.dataTransfer.files[0]);});
$('mode-tabs').onclick=safe(event=>{const button=event.target.closest('[data-mode]');if(button)return changeMode(button.dataset.mode);});$('tool-strip').onclick=safe(event=>{const button=event.target.closest('[data-tool]');if(button)return toolAction(button.dataset.tool);});$('inspector').onclick=safe(event=>{const object=event.target.closest('[data-object]'),annot=event.target.closest('[data-annotation]');if(object)select(S.objects.find(o=>o.index===Number(object.dataset.object)));else if(annot)select(S.annotations.find(a=>a.annotIndex===Number(annot.dataset.annotation)));else if(event.target.closest('button[id]'))return inspectorAction(event.target.closest('button[id]').id);});
$('undo-btn').onclick=safe(()=>undo());$('redo-btn').onclick=safe(()=>undo(true));$('download-btn').onclick=safe(downloadPDF);$('prev-btn').onclick=safe(()=>goto(S.page-1));$('next-btn').onclick=safe(()=>goto(S.page+1));$('page-input').onchange=safe(event=>goto(Number(event.target.value)-1));$('thumbnails').onclick=safe(event=>{const b=event.target.closest('[data-page]');if(b)return goto(Number(b.dataset.page));});$('zoom-select').onchange=safe(async event=>{S.zoom=event.target.value;await render();});
function zoomBy(delta){const size=S.engine?.size(S.page);if(!size)return;S.zoom=clamp((S.zoom==='fit'?S.width/size.width:Number(S.zoom))+delta,.25,3);$('zoom-select').value=String(S.zoom);if(!$('zoom-select').value){const option=document.createElement('option');option.value=String(S.zoom);option.textContent=Math.round(S.zoom*100)+'%';$('zoom-select').append(option);$('zoom-select').value=String(S.zoom);}return render();}
$('zoom-out').onclick=safe(()=>zoomBy(-.25));$('zoom-in').onclick=safe(()=>zoomBy(.25));$('fullscreen-btn').onclick=safe(async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await $('workspace').requestFullscreen();await frame();await render();});$('toggle-pages').onclick=safe(async()=>{const collapsed=$('workspace').querySelector('.page-rail').classList.toggle('collapsed');$('workspace').querySelector('.editor-grid').classList.toggle('rail-collapsed',collapsed);$('toggle-pages').setAttribute('aria-expanded',String(!collapsed));await render();});
$('interaction-layer').onpointerdown=pointerDown;$('interaction-layer').onpointermove=pointerMove;$('interaction-layer').onpointerup=safe(pointerUp);$('interaction-layer').onpointercancel=()=>{S.drag=null;S.pending=null;drawOverlay();};
document.addEventListener('keydown',safe(async event=>{if(!S.engine?.doc||S.busy||$('app-dialog').open||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName))return;const mod=event.ctrlKey||event.metaKey;if(mod&&event.key.toLowerCase()==='s'){event.preventDefault();await downloadPDF();}else if(mod&&event.key.toLowerCase()==='z'){event.preventDefault();await undo(event.shiftKey);}else if(mod&&event.key.toLowerCase()==='y'){event.preventDefault();await undo(true);}else if(event.key==='Delete'||event.key==='Backspace'){if(S.selected){event.preventDefault();await inspectorAction('remove-selected');}}else if(event.key==='Escape'){S.selected=null;S.pending=null;S.tool=S.mode==='forms'?'fill':'select';toolbar();drawOverlay();inspect();}}));
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(S.engine?.doc&&S.zoom==='fit'&&!S.busy)render().catch(fail);},180);});
